// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const data =$input.first().json['memoria 2'] ;

// Tenta converter string para array, se possível
let array;

try {
    // Se for string e JSON válido (ex: '["Oi", "tudo", "bem?"]')
    array = typeof data === 'string' ? JSON.parse(data) : data;

    // Se mesmo após parse ainda não for array, transforma em array com único valor
    if (!Array.isArray(array)) {
        array = [String(array)];
    }

} catch (err) {
    // Se não conseguir dar parse, assume que é uma string simples e cria array com ela
    array = [String(data)];
}

const mensagem_completa = array.join(" ");

return [{ json: { mensagem_completa } }];
